    if check_db_or_user_exists(connection_dict["db_name"], connection_dict["db_username"], config):
        raise ValueError("db or user already exists")

def delete_database(db_name, config):
    with _create_pg_connection(config) as con:
        con.set_isolation_level(ISOLATION_LEVEL_AUTOCOMMIT)
        with con.cursor() as cur:
            try:
                cur.execute('''DROP DATABASE "{}";'''.format(db_name))
            except psycopg2.ProgrammingError as e:
                raise ValueError(e.args[0])

def delete(self, entity):
    try:
        pgcd.delete_database(entity.db_name, self.config)
        pgcd.delete_user(entity.username, self.config)
    except ValueError as e:
        if 'does not exist' in e.args[0]:
            raise PostgraasApiException("Could not delete, does not exist {}".format(entity.db_name))
        else:
